// Passport-issuing countries and territories: ISO 3166-1 alpha-2 codes (lower case) with English names
// generated by Intl.DisplayNames. Reserved/uninhabited/non-country codes are excluded.
const EXCLUDED = new Set(["AC", "AQ", "BV", "CP", "DG", "EA", "EU", "EZ", "HM", "IC", "QO", "TA", "UN", "XA", "XB", "ZZ"]);

export type Country = { code: string; name: string };

function build(): Country[] {
  const names = new Intl.DisplayNames(["en"], { type: "region", fallback: "none" });
  const list: Country[] = [];
  for (let a = 65; a < 91; a++) {
    for (let b = 65; b < 91; b++) {
      const upper = String.fromCharCode(a, b);
      if (EXCLUDED.has(upper)) continue;
      const name = names.of(upper);
      if (name && name !== upper) list.push({ code: upper.toLowerCase(), name });
    }
  }
  return list.sort((x, y) => x.name.localeCompare(y.name, "en"));
}

export const COUNTRIES: readonly Country[] = build();
const BY_CODE = new Map(COUNTRIES.map((c) => [c.code, c.name]));

/** Returns the lower-case code if it is a known country, otherwise null. */
export function normalizeResidency(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const code = value.trim().toLowerCase();
  return BY_CODE.has(code) ? code : null;
}

export function countryName(code: string): string | undefined {
  return BY_CODE.get(code);
}
